def transform(grid):
    from collections import Counter, defaultdict, deque

    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Find the largest connected component of any non-background color:
    # this is the patterned board.
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == background or (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            components.append((color, comp))

    base, board_comp = max(components, key=lambda item: len(item[1]))
    r0 = min(r for r, c in board_comp)
    r1 = max(r for r, c in board_comp)
    c0 = min(c for r, c in board_comp)
    c1 = max(c for r, c in board_comp)

    out = [row[c0:c1 + 1] for row in grid[r0:r1 + 1]]

    # Connected components of marker cells inside the board.
    markers = {
        (r, c)
        for r in range(r0, r1 + 1)
        for c in range(c0, c1 + 1)
        if grid[r][c] == background
    }

    def split_components(cells):
        remaining = set(cells)
        result = []
        while remaining:
            start = remaining.pop()
            q = deque([start])
            comp = [start]
            while q:
                y, x = q.popleft()
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nxt = (y + dy, x + dx)
                    if nxt in remaining:
                        remaining.remove(nxt)
                        q.append(nxt)
                        comp.append(nxt)
            result.append(comp)
        return result

    targets = split_components(markers)

    def normalize(points):
        min_y = min(y for y, x in points)
        min_x = min(x for y, x in points)
        return tuple(sorted((y - min_y, x - min_x) for y, x in points))

    def apply_transform(points, reflected, rotations):
        result = []
        for y, x in points:
            if reflected:
                x = -x
            for _ in range(rotations):
                y, x = -x, y
            result.append((y, x))
        return result

    def shape_key(points):
        return min(
            normalize(apply_transform(points, reflected, rotations))
            for reflected in (False, True)
            for rotations in range(4)
        )

    def half_turn_key(points):
        a = normalize(points)
        b = normalize([(-y, -x) for y, x in points])
        return min(a, b)

    target_groups = defaultdict(list)
    for comp in targets:
        target_groups[shape_key(comp)].append(comp)

    # Gather colored components outside the board.
    outside = {
        (r, c)
        for r in range(h)
        for c in range(w)
        if not (r0 <= r <= r1 and c0 <= c <= c1)
        and grid[r][c] not in (background, base)
    }
    source_by_key = defaultdict(lambda: defaultdict(list))
    for color in set(grid[r][c] for r, c in outside):
        cells = {(r, c) for r, c in outside if grid[r][c] == color}
        for comp in split_components(cells):
            source_by_key[shape_key(comp)][color].append(comp)

    for key, target_comps in target_groups.items():
        candidates = source_by_key.get(key, {})
        if not candidates:
            continue

        target_orientations = {half_turn_key(comp) for comp in target_comps}
        n_targets = len(target_comps)
        best_color = None
        best_score = None

        for color, source_comps in candidates.items():
            best_source_orientations = set()
            for reflected in (False, True):
                for rotations in range(4):
                    orientations = {
                        half_turn_key(apply_transform(comp, reflected, rotations))
                        for comp in source_comps
                    }
                    if len(target_orientations & orientations) > len(
                            target_orientations & best_source_orientations):
                        best_source_orientations = orientations

            covered = len(target_orientations & best_source_orientations)
            missing = len(target_orientations - best_source_orientations)
            extra = len(best_source_orientations - target_orientations)
            count = len(source_comps)
            score = (
                covered,
                -missing,
                -extra,
                int(count == n_targets),
                -abs(count - n_targets),
                -count,
                -color,
            )
            if best_score is None or score > best_score:
                best_score = score
                best_color = color

        if best_color is not None:
            for comp in target_comps:
                for r, c in comp:
                    out[r - r0][c - c0] = best_color

    return out
