    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    def components(cells):
        remaining = set(cells)
        result = []
        while remaining:
            start = remaining.pop()
            q = deque([start])
            comp = [start]
            while q:
                r, c = q.popleft()
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nxt = (r + dr, c + dc)
                    if nxt in remaining:
                        remaining.remove(nxt)
                        q.append(nxt)
                        comp.append(nxt)
            result.append(comp)
        return result

    # The largest non-background component is the patterned panel.
    seen = set()
    all_comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == background or (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            all_comps.append((color, comp))

    base, panel = max(all_comps, key=lambda item: len(item[1]))
    r0 = min(r for r, c in panel)
    r1 = max(r for r, c in panel)
    c0 = min(c for r, c in panel)
    c1 = max(c for r, c in panel)
    out = [row[c0:c1 + 1] for row in grid[r0:r1 + 1]]

    def shape_key(points):
        forms = []
        for reflected in (False, True):
            for rotations in range(4):
                transformed = []
                for y, x in points:
                    if reflected:
                        x = -x
                    for _ in range(rotations):
                        y, x = -x, y
                    transformed.append((y, x))
                min_y = min(y for y, x in transformed)
                min_x = min(x for y, x in transformed)
                forms.append(tuple(sorted(
                    (y - min_y, x - min_x) for y, x in transformed
                )))
        return min(forms)

    targets = components({
        (r, c)
        for r in range(r0, r1 + 1)
        for c in range(c0, c1 + 1)
        if grid[r][c] == background
    })

    outside_by_color = defaultdict(set)
    for r in range(h):
        for c in range(w):
            if (r0 <= r <= r1 and c0 <= c <= c1):
                continue
            color = grid[r][c]
            if color != background and color != base:
                outside_by_color[color].add((r, c))

    source_by_shape = defaultdict(lambda: defaultdict(list))
    color_component_count = {}
    color_cell_count = {}

    for color, cells in outside_by_color.items():
        comps = components(cells)
        color_component_count[color] = len(comps)
        color_cell_count[color] = len(cells)
        for comp in comps:
            source_by_shape[shape_key(comp)][color].append(comp)

    targets_by_shape = defaultdict(list)
    for comp in targets:
        targets_by_shape[shape_key(comp)].append(comp)

    for key, target_comps in targets_by_shape.items():
        candidates = source_by_shape.get(key, {})
        if not candidates:
            continue

        color = max(
            candidates,
            key=lambda col: (
                len(candidates[col]),
                color_component_count[col],
                color_cell_count[col],
                -col,
            ),
        )
        for comp in target_comps:
            for r, c in comp:
                out[r - r0][c - c0] = color

    return out
